import unittest
import mock
from mock import patch
from taf.ul.oam.selenium_coam.pages.login_management import LogoutPage, CoamLoginPage, LabAccessLoginPage


class TestCoamLoginPage(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.WebDriver')
    def setUp(self, mock_driver):
        mock_driver.return_value = mock.MagicMock()
        self.login_page = CoamLoginPage()

    def test_login(self):
        url = "10.57.223.99"
        username = "Nemuadmin"
        password = "nemuuser"
        timeout = 6

        self.login_page._insert_username = mock.MagicMock()
        self.login_page._insert_password = mock.MagicMock()
        self.login_page._click_login_button = mock.MagicMock()
        self.login_page.legal_notice_modal.wait_until_legal_notice_modal_appear = mock.MagicMock()
        self.login_page.legal_notice_modal.confirm = mock.MagicMock()
        self.login_page.reload_modal.wait_until_login_modal_appear = mock.MagicMock()
        self.login_page.reload_modal.confirm = mock.MagicMock()

        self.login_page.login(url, username, password, timeout)
        self.login_page._insert_username.assert_called_once()
        self.login_page._insert_password.assert_called_once()
        self.login_page.legal_notice_modal.wait_until_legal_notice_modal_appear.assert_called()
        self.login_page.legal_notice_modal.confirm.assert_called()
        self.login_page.reload_modal.wait_until_login_modal_appear.assert_called()
        self.login_page.reload_modal.confirm.assert_called()

    def test_login_after_screen_lock(self):
        self.login_page.wait_for_visibility_by_xpath = mock.Mock()
        self.login_page.insert_text_to_enable_element_and_enter = mock.Mock()
        self.login_page.wait_for_visibility_by_xpath = mock.Mock()

        self.login_page.login_after_screen_lock('nemuuser')
        self.login_page.wait_for_visibility_by_xpath.assert_called()
        self.login_page.insert_text_to_enable_element_and_enter.assert_called()
        self.login_page.wait_for_visibility_by_xpath.assert_called()


