class TestLogoutPage(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.CustomWebdriver')
    def setUp(self, mock_driver):
        mock_driver.return_value = mock.MagicMock()
        self.logout_page = LogoutPage()

    def test_logout(self):
        self.logout_page.disable_message_box = mock.MagicMock()
        self.logout_page.wait_until_element_is_clickable = mock.MagicMock()
        self.logout_page.click_enabled_element_after_visible = mock.MagicMock()
        self.logout_page.close_browser = mock.MagicMock()

        self.logout_page.logout(click_timeout=10)

        self.logout_page.click_enabled_element_after_visible.assert_called()
        self.logout_page.close_browser.assert_called()
        self.logout_page.wait_until_element_is_clickable.assert_called()
